fun env level extEntries? =>
  have env := env.setExporting (level != Lean.OLeanLevel.private);
  have __do_jp := fun entries =>
    have kenv := env.toKernelEnv;
    have constNames :=
      Lean.SMap.foldStage2 (fun names name x => names.push name) #[] kenv.constants;
    have constants :=
      if (level == Lean.OLeanLevel.private) = true then
        Lean.SMap.foldStage2 (fun cs x c => cs.push c) #[] kenv.constants
      else
        (Array.filterMap
              (fun n =>
                env.find? n <|> guard (Lean.looksLikeOldCodegenName✝ n = true) *> kenv.find? n)
              constNames).qsort
          fun c₁ c₂ => c₁.name.quickCmp c₂.name == Ordering.lt;
    have constNames := Array.map (fun x => x.name) constants;
    pure
      (have __src := env.header;
      { isModule := __src.isModule, imports := __src.imports, constNames := constNames,
        constants := constants, extraConstNames := Lean.getIRExtraConstNames✝ env level,
        entries := entries });
  match extEntries? with
  | some ee => do
    let entries ← pure (ee.get level)
    __do_jp entries
  | none => do
    let ee ← Lean.computeExtEntries✝ env
    let entries ← pure (ee.get level)
    __do_jp entries

