fun l₁ l₂ =>
  { reported := l₁.reported ++ l₂.reported, unreported := l₁.unreported ++ l₂.unreported,
    loggedKinds := Std.TreeSet.merge l₁.loggedKinds l₂.loggedKinds }

fun msg includeEndPos =>
  (have str := msg.data;
    have endPos := if includeEndPos = true then msg.endPos else none;
    have __do_jp := fun __r str =>
      have __do_jp := fun __r str =>
        have __do_jp := fun __r str => pure str;
        if (str.isEmpty || str.back != '\n') = true then
          have str := str ++ "\n";
          __do_jp () str
        else __do_jp () str;
      match msg.severity with
      | Lean.MessageSeverity.information => __do_jp () str
      | Lean.MessageSeverity.warning =>
        have str :=
          Lean.mkErrorStringWithPos msg.fileName msg.pos str endPos (some "warning")
            (Lean.errorNameOfKind? msg.kind);
        __do_jp () str
      | Lean.MessageSeverity.error =>
        have str :=
          Lean.mkErrorStringWithPos msg.fileName msg.pos str endPos (some "error")
            (Lean.errorNameOfKind? msg.kind);
        __do_jp () str;
    if (msg.caption == "") = true then __do_jp () str
    else
      have str := msg.caption ++ ":\n" ++ str;
      __do_jp () str).run

{
  toMessageData := fun x =>
    match x with
    | none => (Lean.MessageData.ofFormat ∘ Std.format) "<not-available>"
    | some e => Lean.toMessageData e }
